recipes.code:
{
  "inputs": [
    {
      "id": "mockhero-api-key",
      "type": "promptString",
      "description": "MockHero API key (optional — without it, generation runs as a free preview up to 100 records per request; get a key at https://mockhero.dev or via the create_agent_checkout tool)",
      "password": true
    }
  ],
  "servers": {
    "mockhero": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@mockherodev/mcp-server@0.2.0"
      ],
      "env": {
        "MOCKHERO_API_KEY": "${input:mockhero-api-key}",
        "MOCKHERO_API_BASE": "<mockhero-api-base>"
      }
    }
  }
}
